import SwiftUI

struct LeagueView: View {
    @EnvironmentObject private var store: AppStore
    var body: some View { NavigationStack { ScrollView { VStack(alignment:.leading,spacing:15){Eyebrow(text:"DIVISION ARGENT");Text("La ligue des stratèges").font(.largeTitle.bold());Text("Les six premiers montent en Or.").foregroundStyle(.konsensMuted);VStack(spacing:0){ForEach(store.leaders){leader in HStack{Text("\(leader.rank)").font(.body.monospacedDigit()).foregroundStyle(.konsensMuted).frame(width:25);Text(leader.initials).font(.caption.bold()).frame(width:38,height:38).background(Color.white.opacity(.08),in:Circle());VStack(alignment:.leading){Text(leader.name).bold();Text(leader.isCurrentUser ? "Toi · série de 7 jours":"Actif aujourd’hui").font(.caption2).foregroundStyle(.konsensMuted)};Spacer();Text("+\(leader.score,specifier:"%.1f") %").font(.subheadline.monospacedDigit().bold()).foregroundStyle(.konsensGreen)}.padding(leader.isCurrentUser ? 13:15).background(leader.isCurrentUser ? Color.konsensGreen.opacity(.08):Color.clear,in:RoundedRectangle(cornerRadius:14))}}.panel();Button("Inviter un adversaire"){store.showToast("Code de ligue copié : KNS-2026")}.font(.headline).foregroundStyle(Color.konsensBackground).frame(maxWidth:.infinity).padding(14).background(Color.konsensGreen,in:RoundedRectangle(cornerRadius:13))}.padding(18)}.background(Color.konsensBackground).navigationTitle("Ligue").navigationBarTitleDisplayMode(.inline)} }
}
